package circles.event

import circles.encoding.ByteString
import circles.encoding.CborBytes
import circles.encoding.CborMap
import circles.encoding.CborText
import circles.policy.CircleId
import circles.policy.MemberId

/**
 * One fixed envelope and its bytes, produced by an independent Python reference encoder (not this code), so the
 * encoding is pinned the same way on the JVM and in JS. The signed vector lives in the JVM tests.
 */
object EnvelopeVectors {
    val circle = CircleId("11".repeat(16))
    val member = MemberId("22".repeat(16))
    val device = DeviceId("33".repeat(16))
    val signPub: ByteString = ByteString.fromHex("44".repeat(32))!!
    val boxPub: ByteString = ByteString.fromHex("55".repeat(32))!!
    val fakeSig: ByteString = ByteString.fromHex("66".repeat(64))!!

    val unsigned = Envelope(
        v = 0,
        circle = circle,
        author = member,
        device = device,
        type = "circle.create",
        day = 20000,
        ctr = 0,
        epoch = 0,
        public = CborMap.of(
            "member" to CborText(member.v),
            "device" to CborText(device.v),
            "signPub" to CborBytes(signPub),
            "boxPub" to CborBytes(boxPub),
        ),
        nonce = ByteString.EMPTY,
        encrypted = ByteString.EMPTY,
        sig = ByteString.EMPTY,
    )

    val withFakeSig: Envelope = unsigned.copy(sig = fakeSig)

    const val SIGNING_HEX =
        ""

    const val CANONICAL_HEX =
        ""

    /** BLAKE2b-256 of [CANONICAL_HEX], from Python's hashlib. */
    const val CANONICAL_ID = "8a4bab1cdca4d8603ed59fd8594e117ec2b59dedb810e6ce4eefe92b248027e1"
}
